{{pins}}
#include <Adafruit_NeoPixel.h>

const int PIXELS = 12;
Adafruit_NeoPixel ring(PIXELS, NEOPIXEL_PIN, NEO_GRB + NEO_KHZ800);

void setup() {
  ring.begin();
  ring.setBrightness(40);  // not too bright for your eyes
}

void loop() {
  // Red, green, blue: each 0 to 255.
  for (int i = 0; i < PIXELS; i++) {
    ring.setPixelColor(i, ring.Color(0, 0, 255));
  }
  ring.show();
}

