{{pins}}
#include <Adafruit_NeoPixel.h>

const int PIXELS = 12;
Adafruit_NeoPixel ring(PIXELS, NEOPIXEL_PIN, NEO_GRB + NEO_KHZ800);

int mode = 0;          // 0: knob colour, 1: rainbow, 2: off
int lastButton = HIGH;
long rainbowStart = 0;

void setup() {
  ring.begin();
  ring.setBrightness(40);
  pinMode(BUTTON_PIN, INPUT_PULLUP);
}

void loop() {
  int button = digitalRead(BUTTON_PIN);
  if (button == LOW && lastButton == HIGH) {
    mode = (mode + 1) % 3;  // 0, 1, 2, 0, 1, 2...
    delay(50);
  }
  lastButton = button;

  if (mode == 0) {
    long hue = map(analogRead(POT_PIN), 0, ANALOG_MAX, 0, 65535);
    for (int i = 0; i < PIXELS; i++) {
      ring.setPixelColor(i, ring.ColorHSV(hue));
    }
  } else if (mode == 1) {
    rainbowStart += 256;
    for (int i = 0; i < PIXELS; i++) {
      ring.setPixelColor(i, ring.ColorHSV(rainbowStart + i * 65536L / PIXELS));
    }
  } else {
    ring.clear();
  }
  ring.show();
  delay(20);
}
